import type { ComponentProps } from "react"
import { cn } from "@/registry/default/lib/utils"

export function NavigationMenu({ className, ...props }: ComponentProps<"nav">) { return <nav aria-label="Primary navigation" data-slot="navigation-menu" className={cn("flex items-center gap-1", className)} {...props} /> }
export function NavigationMenuLink({ className, active, ...props }: ComponentProps<"a"> & { active?: boolean }) { return <a aria-current={active ? "page" : undefined} data-slot="navigation-menu-link" className={cn("rounded-md px-3 py-2 text-sm text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground", active && "bg-accent font-medium text-accent-foreground", className)} {...props} /> }
